function run(command, args, cwd) {
  console.log(`[prepare] ${command} ${args.join(" ")}  (cwd: ${path.relative(repoRoot, cwd) || "."})`);
  const result = spawnSync(command, args, { cwd, stdio: "inherit" });
  return result.status === 0;
}

